impl flatbuffers::Verifiable for OpEntry<'_> {
    #[inline]
    fn run_verifier(
        v: &mut flatbuffers::Verifier,
        pos: usize,
    ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
        use self::flatbuffers::Verifiable;
        v.visit_table(pos)?
            .visit_union::<Op, _>(
                "op_type",
                Self::VT_OP_TYPE,
                "op",
                Self::VT_OP,
                true,
                |key, v, pos| match key {
                    Op::Set => {
                        v.verify_union_variant::<flatbuffers::ForwardsUOffset<Set>>("Op::Set", pos)
                    }
                    Op::RmRow => v.verify_union_variant::<flatbuffers::ForwardsUOffset<RmRow>>(
                        "Op::RmRow",
                        pos,
                    ),
                    Op::RestoreRow => v
                        .verify_union_variant::<flatbuffers::ForwardsUOffset<RestoreRow>>(
                            "Op::RestoreRow",
                            pos,
                        ),
                    Op::Append => v.verify_union_variant::<flatbuffers::ForwardsUOffset<Append>>(
                        "Op::Append",
                        pos,
                    ),
                    _ => Ok(()),
                },
            )?
            .finish();
        Ok(())
    }
}
