impl Serialize for OpEntry<'_> {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        let mut s = serializer.serialize_struct("OpEntry", 2)?;
        s.serialize_field("op_type", &self.op_type())?;
        match self.op_type() {
            Op::NONE => (),
            Op::Set => {
                let f = self
                    .op_as_set()
                    .expect("Invalid union table, expected `Op::Set`.");
                s.serialize_field("op", &f)?;
            }
            Op::RmRow => {
                let f = self
                    .op_as_rm_row()
                    .expect("Invalid union table, expected `Op::RmRow`.");
                s.serialize_field("op", &f)?;
            }
            Op::RestoreRow => {
                let f = self
                    .op_as_restore_row()
                    .expect("Invalid union table, expected `Op::RestoreRow`.");
                s.serialize_field("op", &f)?;
            }
            Op::Append => {
                let f = self
                    .op_as_append()
                    .expect("Invalid union table, expected `Op::Append`.");
                s.serialize_field("op", &f)?;
            }
            _ => unimplemented!(),
        }
        s.end()
    }
}

